Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

(* [comment removed for export] *)
Record srp : Type := mk_srp {
  sr_DS : Z; sr_DD : Z; sr_NS : Z; sr_ND : Z;   (* [comment removed for export] *)
  sr_w : Z; sr_h : Z; sr_wpls : Z; sr_c : Z }.
Definition sr_ok (p : srp) : Prop :=
  0 < sr_w p <= 20000 /\ 0 < sr_h p <= 20000 /\ sr_wpls p = (sr_w p * 8 + 31) / 32
  /\ sr_NS p = 4 * (sr_wpls p * sr_h p) /\ 0 < sr_NS p <= 0x4000000
  /\ sr_ND p = 4 * (sr_w p * sr_h p) /\ 0 < sr_ND p <= 0x4000000
  /\ arange (sr_DS p) (sr_NS p) /\ sr_DS p mod 4 = 0 /\ arange (sr_DD p) (sr_ND p) /\ sr_DD p mod 4 = 0
  /\ 0 <= sr_c p <= 2.
(* [comment removed for export] *)
Definition sr_ro (p : srp) (m : mem) : Prop := wr_at asegs m (sr_DS p) (sr_NS p) /\ acc asegs m (sr_DS p) (sr_NS p).


(* [comment removed for export] *)
Definition srb_j_exit (p : srp) (LS LD : Z) (sp gp tp s0 s1 a0 a2 a3 a4 s4 s7 s8 s9 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
  : machine_state -> Prop :=
  fun ms' => exists (t1' t5' a1' s2' s3' s5' s6' : word) (m' : mem),
    ms' = MS (mkR (Z_to_bv 64 (LD + sr_c p)) sp gp tp (Z_to_bv 64 (4 * sr_w p)) t1' (Z_to_bv 64 3) s0 s1 a0 a1' a2 a3 a4 (Z_to_bv 64 1) (Z_to_bv 64 1)
                  (Z_to_bv 64 (sr_c p + LD)) s2' s3' s4 s5' s6' s7 s8 s9 (Z_to_bv 64 2147450880) s11 (Z_to_bv 64 LS) (Z_to_bv 64 LD) t5' (Z_to_bv 64 LD))
             F (Z_to_bv 64 0x9ef00) fc None m' (seg_rom asegs)
    /\ munch [(sr_DD p, sr_DD p + sr_ND p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma srb_j_loop : forall (n : nat) (p : srp) (j LS LD : Z)
    (sp gp tp s0 s1 a0 a1 a2 a3 a4 s2 s4 s7 s8 s9 s11 t1 t5 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = sr_w p - j -> 0 <= j -> (1 <= n)%nat -> sr_ok p ->
  sr_DS p <= LS -> LS + sr_w p <= sr_DS p + sr_NS p -> sr_DD p <= LD -> LD + 4 * sr_w p <= sr_DD p + sr_ND p -> LD mod 4 = 0 ->
  (forall m', munch [(sr_DD p, sr_DD p + sr_ND p)] m m' -> wmono asegs m m' -> sr_ro p m') ->
  wr_at asegs m (sr_DD p) (sr_ND p) -> acc asegs m (sr_DD p) (sr_ND p) -> mem_inv asegs m ->
  evt asegs (srb_j_exit p LS LD sp gp tp s0 s1 a0 a2 a3 a4 s4 s7 s8 s9 s11 F fc m)
    (MS (mkR (Z_to_bv 64 (LD + sr_c p)) sp gp tp (Z_to_bv 64 (4 * sr_w p)) t1 (Z_to_bv 64 3) s0 s1 a0 a1 a2 a3 a4 (Z_to_bv 64 1) (Z_to_bv 64 1)
             (Z_to_bv 64 (sr_c p + LD)) s2 (Z_to_bv 64 (4 * j)) s4 (Z_to_bv 64 (LS + j)) (Z_to_bv 64 (LS + j)) s7 s8 s9 (Z_to_bv 64 2147450880) s11
             (Z_to_bv 64 LS) (Z_to_bv 64 LD) t5 (Z_to_bv 64 LD))
        F (Z_to_bv 64 0x9efb0) fc None m (seg_rom asegs)).
Proof.
