(* [comment removed for export] *)
Definition srb_ro (p : srp) (rf : Z) (m : mem) : Prop :=
  sr_ro p m /\ rw_cells asegs m (rf + 24) [C8 (Z_to_bv 64 (sr_DD p + sr_c p)); C8 (Z_to_bv 64 (sr_c p)); C8 (Z_to_bv 64 (sr_w p)); C8 (Z_to_bv 64 (sr_h p))].

(* [comment removed for export] *)
Definition srb_i_exit (p : srp) (rf : Z) (sp gp tp s0 s8 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' a0' a2' a3' a4' a5' a6' a7' s2' s3' s4' s5' s6' s7' s9' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1' (Z_to_bv 64 3) s0 (Z_to_bv 64 rf) a0' (Z_to_bv 64 0) a2' a3' a4' a5' a6' a7'
                  s2' s3' s4' s5' s6' s7' s8 s9' (Z_to_bv 64 2147450880) s11 t3' t4' t5' t6')
             F (Z_to_bv 64 0x9f15c) fc None m' (seg_rom asegs)
    /\ munch [(sr_DD p, sr_DD p + sr_ND p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma srb_i_loop : forall (n : nat) (p : srp) (rf i : Z)
    (ra sp gp tp t1 s0 a1 a7 s2 s3 s5 s6 s8 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = sr_h p - i -> 0 <= i -> (1 <= n)%nat -> sr_ok p ->
  (forall m', munch [(sr_DD p, sr_DD p + sr_ND p)] m m' -> wmono asegs m m' -> srb_ro p rf m') ->
  wr_at asegs m (sr_DD p) (sr_ND p) -> acc asegs m (sr_DD p) (sr_ND p) -> mem_inv asegs m ->
  evt asegs (srb_i_exit p rf sp gp tp s0 s8 s11 F fc m)
    (MS (mkR ra sp gp tp (Z_to_bv 64 (4 * sr_w p)) t1 (Z_to_bv 64 3) s0 (Z_to_bv 64 rf) (Z_to_bv 64 (sr_w p)) a1
             (Z_to_bv 64 (i * sr_wpls p)) (Z_to_bv 64 (i * sr_w p)) (Z_to_bv 64 i) (Z_to_bv 64 1) (Z_to_bv 64 1) a7
             s2 s3 (Z_to_bv 64 (sr_wpls p)) s5 s6 (Z_to_bv 64 (sr_DD p)) s8 (Z_to_bv 64 (sr_DS p)) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x9ef18) fc None m (seg_rom asegs)).
