(* [comment removed for export] *)
Record grp : Type := mk_grp {
  gr_DS : Z; gr_DD : Z; gr_NS : Z; gr_ND : Z;   (* [comment removed for export] *)
  gr_w : Z; gr_h : Z; gr_wpld : Z; gr_c : Z;
  gr_FW : Z; gr_FH : Z }.                        (* [comment removed for export] *)
Definition gr_ok (p : grp) : Prop :=
  0 < gr_w p <= 20000 /\ 0 < gr_h p <= 20000 /\ gr_wpld p = (gr_w p * 8 + 31) / 32
  /\ gr_NS p = 4 * (gr_w p * gr_h p) /\ 0 < gr_NS p <= 0x4000000
  /\ gr_ND p = 4 * (gr_wpld p * gr_h p) /\ 0 < gr_ND p <= 0x4000000
  /\ arange (gr_DS p) (gr_NS p) /\ gr_DS p mod 4 = 0 /\ arange (gr_DD p) (gr_ND p) /\ gr_DD p mod 4 = 0
  /\ 0 <= gr_c p <= 2
  /\ arange (gr_FW p) 4 /\ gr_FW p mod 4 = 0 /\ arange (gr_FH p) 4 /\ gr_FH p mod 4 = 0
  /\ (gr_DD p + gr_ND p <= gr_DS p \/ gr_DS p + gr_NS p <= gr_DD p)
  /\ (gr_DD p + gr_ND p <= gr_FW p \/ gr_FW p + 4 <= gr_DD p) /\ (gr_DD p + gr_ND p <= gr_FH p \/ gr_FH p + 4 <= gr_DD p).
(* [comment removed for export] *)
Definition gr_ro (p : grp) (m : mem) : Prop :=
  rw_cells asegs m (gr_FW p) [C4 (Z_to_bv 64 (gr_w p))] /\ rw_cells asegs m (gr_FH p) [C4 (Z_to_bv 64 (gr_h p))]
  /\ wr_at asegs m (gr_DS p) (gr_NS p) /\ acc asegs m (gr_DS p) (gr_NS p).

(* [comment removed for export] *)
Definition grb_j_exit (p : grp) (LS LD : Z) (sp gp tp s0 s1 a3 a4 a5 s4 s5 s6 s7 s10 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
  : machine_state -> Prop :=
  fun ms' => exists (t1' t5' t6' a0' a2' s2' s8' : word) (m' : mem),
    ms' = MS (mkR (Z_to_bv 64 (LS + gr_c p)) sp gp tp (Z_to_bv 64 (gr_c p + LS)) t1' (Z_to_bv 64 3) s0 s1 a0' (Z_to_bv 64 LD) a2' a3 a4 a5
