Lemma grb_j_loop : forall (n : nat) (p : grp) (j LS LD : Z)
    (sp gp tp s0 s1 a0 a2 a3 a4 a5 s2 s4 s5 s6 s7 s10 t5 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = gr_w p - j -> 0 <= j -> (1 <= n)%nat -> gr_ok p ->
  gr_DS p <= LS -> LS + 4 * gr_w p <= gr_DS p + gr_NS p -> LS mod 4 = 0 ->
  gr_DD p <= LD -> LD + gr_w p <= gr_DD p + gr_ND p ->
  (forall m', munch [(gr_DD p, gr_DD p + gr_ND p)] m m' -> wmono asegs m m' -> gr_ro p m') ->
  wr_at asegs m (gr_DD p) (gr_ND p) -> acc asegs m (gr_DD p) (gr_ND p) -> mem_inv asegs m ->
  evt asegs (grb_j_exit p LS LD sp gp tp s0 s1 a3 a4 a5 s4 s5 s6 s7 s10 F fc m)
    (MS (mkR (Z_to_bv 64 (LS + gr_c p)) sp gp tp (Z_to_bv 64 (gr_c p + LS)) (Z_to_bv 64 (4 * j)) (Z_to_bv 64 3) s0 s1 a0 (Z_to_bv 64 LD) a2 a3 a4 a5
             (Z_to_bv 64 1) (Z_to_bv 64 1) s2 (Z_to_bv 64 (gr_FW p)) s4 s5 s6 s7 (Z_to_bv 64 (LD + j)) (Z_to_bv 64 LS) s10 (Z_to_bv 64 2147450880)
             (Z_to_bv 64 LS) (Z_to_bv 64 LD) t5 (Z_to_bv 64 j))
        F (Z_to_bv 64 0x9e9ec) fc None m (seg_rom asegs)).
