(* [comment removed for export] *)
Definition grb_ro (p : grp) (rf : Z) (m : mem) : Prop :=
  gr_ro p m /\ rw_cells asegs m (rf + 32) [C8 (Z_to_bv 64 (gr_DS p + gr_c p)); C8 (Z_to_bv 64 (gr_c p)); C8 (Z_to_bv 64 (gr_FH p)); C8 (Z_to_bv 64 (gr_DS p))].

(* [comment removed for export] *)
Definition grb_i_exit (p : grp) (rf : Z) (sp gp tp s0 s4 s10 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' a0' a1' a2' a3' a4' a5' s2' s8' s9' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1' (Z_to_bv 64 3) s0 (Z_to_bv 64 rf) a0' a1' a2' a3' a4' a5' (Z_to_bv 64 1) (Z_to_bv 64 1)
                  s2' (Z_to_bv 64 (gr_FW p)) s4 (Z_to_bv 64 (gr_w p)) (Z_to_bv 64 (gr_wpld p)) (Z_to_bv 64 (gr_DD p)) s8' s9' s10 (Z_to_bv 64 2147450880)
                  t3' t4' t5' t6')
             F (Z_to_bv 64 0x9eb04) fc None m' (seg_rom asegs)
    /\ munch [(gr_DD p, gr_DD p + gr_ND p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma grb_i_loop : forall (n : nat) (p : grp) (rf i : Z)
    (ra sp gp tp t0 t1 s0 a0 a1 a2 s2 s4 s8 s9 s10 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = gr_h p - i -> 0 <= i -> (1 <= n)%nat -> gr_ok p ->
  0 < rf -> rf + 64 <= gr_DD p \/ gr_DD p + gr_ND p <= rf ->
  (forall m', munch [(gr_DD p, gr_DD p + gr_ND p)] m m' -> wmono asegs m m' -> grb_ro p rf m') ->
  wr_at asegs m (gr_DD p) (gr_ND p) -> acc asegs m (gr_DD p) (gr_ND p) -> mem_inv asegs m ->
